 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{case['title'][0]} — Camilo Vergara</title><link rel="stylesheet" href="../../styles.css"><style>html[lang=en] [lang=es],html[lang=es] [lang=en]{{display:none}}main{{max-width:1000px;margin:auto;padding:40px 24px}}section{{margin:36px 0}}p{{max-width:75ch}}h1{{font-family:var(--font-display);font-size:clamp(2rem,4vw,3.5rem);line-height:1.15;margin:32px 0}}h2{{font-size:1.3rem;margin-bottom:12px}}img{{width:100%;height:auto;margin:28px 0}}.downloads{{display:flex;gap:18px;flex-wrap:wrap}}button{{font:inherit;padding:8px 14px;background:var(--surface);border:1px solid var(--border);cursor:pointer}}</style></head><body><main><nav class="downloads"><a href="../../index.html#projects">← Portfolio</a><button onclick="document.documentElement.lang='en'">English</button><button onclick="document.documentElement.lang='es'">Español</button></nav><h1><span lang="en">{case['title'][0]}</span><span lang="es">{case['title'][1]}</span></h1><p lang="en">{case['domain'][0]}</p><p lang="es">{case['domain'][1]}</p><img src="evidence.png" alt="Computed analytical charts; results and limitations described below" width="1950" height="720">{sections}<section><h2>Downloads / Descargas</h2><div class="downloads"><a href="dashboard.xlsx" download>Excel + PivotTable</a><a href="evidence-pack.zip" download>Evidence pack / Paquete</a><a href="https://github.com/Chrov/Portfolio/tree/main/case-studies/{slug}">GitHub</a><a href="{case['source']}">Source / Fuente</a></div></section></main></body></html>'''
