page=page[:start]+f'''    <section id="projects" class="section"><div class="container"><h2 class="section__title" data-i18n="proj.title">{updates['proj.title'][0]}</h2><p class="section__lead" data-i18n="proj.lead">{updates['proj.lead'][0]}</p>{''.join(cards)}</div></section>'''+page[end:]
